result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/seatgen.py", "content": "#!/usr/bin/env python3
"""Exam seating generator (stdlib only).

Usage:
    python seatgen.py input.json --seed 7

Input JSON format:
    {
        "rows": int,
        "cols": int,
        "broken_seats": [[r, c], ...],
        "students": [{"id": str, "course": str}, ...]
    }

Constraint: no two students taking the same course may sit in
orthogonally adjacent seats. Broken seats stay empty.

Solved via backtracking; candidate student order is shuffled with a
seeded RNG for reproducibility. Writes chart.json and prints a grid.
"""

import argparse
import json
import random
import sys


def neighbors(r, c, rows, cols):
    if r > 0:
        yield r - 1, c
    if r < rows - 1:
        yield r + 1, c
    if c > 0:
        yield r, c - 1
    if c < cols - 1:
        yield r, c + 1


def solve(rows, cols, broken_seats, students, seed):
    """Return a seating dict or None if infeasible."""
    broken = {(r, c) for r, c in broken_seats}
    working = [
        (r, c)
        for r in range(rows)
        for c in range(cols)
        if (r, c) not in broken
    ]
    if len(students) > len(working):
        return None

    rng = random.Random(seed)
    order = list(range(len(students)))
    # Seeded shuffle of the candidate order in which students are tried.
    rng.shuffle(order)

    seat_of = {}          # student index -> (r, c)
    assignment = {}       # (r, c) -> student index

    def ok(idx, pos):
        r, c = pos
        course = students[idx]["course"]
        for nb in neighbors(r, c, rows, cols):
            j = assignment.get(nb)
            if j is not None and students[j]["course"] == course:
                return False
        return True

    def backtrack(i):
        if i == len(order):
            return True
        idx = order[i]
        for pos in working:
            if pos in assignment:
                continue
            if ok(idx, pos):
                assignment[pos] = idx
                seat_of[idx] = pos
                if backtrack(i + 1):
                    return True
                del assignment[pos]
                del seat_of[idx]
        return False

    if not backtrack(0):
        return None

    seating = [[None] * cols for _ in range(rows)]
    for pos, idx in assignment.items():
        r, c = pos
        seating[r][c] = {"id": students[idx]["id"],
                         "course": students[idx]["course"]}
    return {
        "rows": rows,
        "cols": cols,
        "seating": seating,
        "seed": seed,
    }


def render(seating):
    lines = []
    width = max(
        [len(s["id"]) for row in seating for s in row if s] + [4]
    )
    for row in seating:
        cells = []
        for s in row:
            if s is None:
                cells.append("." .center(width))
            else:
                cells.append(s["id"].center(width))
        lines.append(" | ".join(cells))
    return "\n".join(lines)


def main(argv=None):
    ap = argparse.ArgumentParser(description="Exam seating generator")
    ap.add_argument("input", help="input JSON file")
    ap.add_argument("--seed", type=int, default=0, help="RNG seed")
    args = ap.parse_args(argv)

    with open(args.input) as f:
        data = json.load(f)

    result = solve(
        data["rows"], data["cols"], data["broken_seats"], data["students"],
        args.seed,
    )
    if result is None:
        print("infeasible")
        return 1

    with open("chart.json", "w") as f:
        json.dump(result, f, indent=2)
    print(render(result["seating"]))
    return 0


if __name__ == "__main__":
    sys.exit(main())
"})
print(result)

result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/verify.py", "content": "#!/usr/bin/env python3
"""Independently verify a seating chart produced by seatgen.py.

Usage: python verify.py input.json chart.json

Re-checks every constraint from scratch and exits nonzero on any
violation.
"""

import json
import sys


def main(argv=None):
    argv = argv if argv is not None else sys.argv[1:]
    if len(argv) != 2:
        print("usage: verify.py input.json chart.json", file=sys.stderr)
        return 2

    with open(argv[1]) as f:
        inp = json.load(f)
    with open(argv[2]) as f:
        chart = json.load(f)

    errors = []
    rows, cols = inp["rows"], inp["cols"]
    broken = {tuple(x) for x in inp.get("broken_seats", [])}
    students = inp["students"]
    seating = chart["seating"]

    # Structure checks.
    if chart.get("rows") != rows or chart.get("cols") != cols:
        errors.append("chart dimensions do not match input")
    if len(seating) != rows:
        errors.append(f"expected {rows} rows, got {len(seating)}")
        seating = seating[:rows]

    placed = []
    occupied_broken = []
    duplicates = {}
    out_of_bounds = []
    adjacency = []

    for r, row in enumerate(seating):
        if len(row) != cols:
            errors.append(
                f"row {r}: expected {cols} cells, got {len(row)}")
        for c, cell in enumerate(row[:cols]):
            if cell is None:
                continue
            sid = cell["id"]
            course = cell["course"]
            if (r, c) in broken:
                occupied_broken.append((r, c))
            placed.append(sid)
            duplicates.setdefault(sid, []).append((r, c))
            # Orthogonal adjacency against already-seen neighbors.
            for nr, nc in ((r - 1, c), (r, c - 1)):
                if 0 <= nr < len(seating) and 0 <= nc < cols:
                    other = seating[nr][nc]
                    if other and other["course"] == course:
                        adjacency.append((sid, other["id"], course))

    for sid, spots in duplicates.items():
        if len(spots) > 1:
            errors.append(f"student {sid} seated multiple times: {spots}")
    if sorted(placed) != sorted(s["id"] for s in students):
        missing = sorted(set(s["id"] for s in students) - set(placed))
        extra = sorted(set(placed) - set(s["id"] for s in students))
        if missing:
            errors.append(f"students not seated: {missing}")
        if extra:
            errors.append(f"unknown students seated: {extra}")
    if occupied_broken:
        errors.append(f"broken seats occupied: {occupied_broken}")
    for sid, oid, course in adjacency:
        errors.append(
            f"adjacent same-course students {sid} and {oid} ({course})")

    # Cross-check courses against the roster.
    roster = {s["id"]: s["course"] for s in students}
    for r, row in enumerate(seating):
        for c, cell in enumerate(row):
            if cell and roster.get(cell["id"]) not in (cell["course"], None):
                errors.append(
                    f"student {cell['id']} has wrong course at ({r},{c})")

    if errors:
        for e in errors:
            print(f"VIOLATION: {e}", file=sys.stderr)
        return 1
    print(f"OK: {len(placed)} students seated, all constraints satisfied.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
"})
